defmodule Mix.Tasks.Gen.Contracts.RuntimeMetadata do
  @moduledoc false

  alias Mix.Tasks.Gen.Contracts.{Renderer, TypespecParser}

  def render(modules) do
    header =
      "// AUTO-GENERATED by mix gen.contracts -- DO NOT EDIT\n// Source: graph inspector contracts\n\n"

    contracts =
      modules
      |> Enum.map_join("\n", fn module ->
        fields =
          module
          |> TypespecParser.parse()
          |> Enum.map_join(",\n", &field_metadata(&1, module.contract_meta()))

        fields =
          if fields == "" do
            "    fields: [],"
          else
            "    fields: [\n#{fields},\n    ],"
          end

        "  #{inspect(Renderer.module_namespace(module))}: {\n#{fields}\n  },"
      end)

    mappings =
      [
        discriminant_mapping("nodeDataContracts", NetworkDefense.Graph.Contracts.Node),
        discriminant_mapping("edgeDataContracts", NetworkDefense.Graph.Contracts.Edge)
      ]
      |> Enum.join("\n\n")

    header <>
      ~s"""
      export type FieldKind =
        "string" | "number" | "boolean" | "enum" | "object" | "list" | "unknown";

      export interface FieldMetadata {
        name: string;
        kind: FieldKind;
        nullable: boolean;
        choices?: readonly string[];
        contract?: string;
        itemContract?: string;
      }

      export interface ContractMetadata {
        fields: readonly FieldMetadata[];
      }

      export const contractMetadata = {
      #{contracts}
      } as const satisfies Readonly<Record<string, ContractMetadata>>;

      """ <> mappings <> "\n"
  end

  defp field_metadata({name, type}, metadata) do
    enum_values = metadata |> Map.get(:enum_values, []) |> Keyword.get(name)
    {nullable, type} = unwrap_nullable(type)
    details = type_details(type, enum_values)

    attributes =
      [
        "name: #{inspect(to_string(name))}",
        "kind: #{inspect(details.kind)}",
        "nullable: #{nullable}"
        | details.attributes
      ]
      |> Enum.map_join("\n", &format_attribute/1)

    "      {\n#{attributes}\n      }"
  end

  defp format_attribute(attribute) do
    if String.length(attribute) > 72 do
      [name, value] = String.split(attribute, ": ", parts: 2)
      "        #{name}:\n          #{value},"
    else
      "        #{attribute},"
    end
  end

  defp type_details(_type, enum_values) when is_list(enum_values) and enum_values != [] do
    %{kind: "enum", attributes: ["choices: #{inspect(Enum.map(enum_values, &to_string/1))}"]}
  end

  defp type_details({:type, _, :list, [item]}, _enum_values) do
    attributes =
      case contract_reference(item) do
        nil -> []
        module -> ["itemContract: #{inspect(Renderer.module_namespace(module))}"]
      end

    %{kind: "list", attributes: attributes}
  end

  defp type_details(type, _enum_values) do
    case contract_reference(type) do
      nil ->
        %{kind: primitive_kind(type), attributes: []}

      module ->
        %{kind: "object", attributes: ["contract: #{inspect(Renderer.module_namespace(module))}"]}
    end
  end

  defp unwrap_nullable({:type, _, :union, members} = union) do
    case Enum.split_with(members, &match?({:atom, _, nil}, &1)) do
      {[_ | _], [type]} -> {true, type}
      _ -> {false, union}
    end
  end

  defp unwrap_nullable(type), do: {false, type}

  defp primitive_kind({:remote_type, _, [{:atom, _, String}, {:atom, _, :t}, _]}), do: "string"
  defp primitive_kind({:remote_type, _, [{:atom, _, Integer}, {:atom, _, :t}, _]}), do: "number"
  defp primitive_kind({:remote_type, _, [{:atom, _, Float}, {:atom, _, :t}, _]}), do: "number"
  defp primitive_kind({:remote_type, _, [{:atom, _, Boolean}, {:atom, _, :t}, _]}), do: "boolean"

  defp primitive_kind({:type, _, type, []})
       when type in [:integer, :float, :non_neg_integer, :pos_integer], do: "number"

  defp primitive_kind({:type, _, :boolean, []}), do: "boolean"
  defp primitive_kind({:type, _, type, []}) when type in [:atom, :binary], do: "string"
  defp primitive_kind(_type), do: "unknown"

  defp contract_reference({:remote_type, _, [{:atom, _, module}, {:atom, _, :t}, _]})
       when module not in [String, Integer, Float, Boolean],
       do: module

  defp contract_reference(_type), do: nil

  defp discriminant_mapping(name, module) do
    variants = module.contract_meta() |> Map.fetch!(:discriminant) |> Keyword.fetch!(:variants)

    entries =
      Enum.map_join(variants, "\n", &discriminant_entry/1)

    "export const #{name} = {\n#{entries}\n} as const;"
  end

  defp discriminant_entry({tag, data_module}) do
    tag = to_string(tag)
    value = inspect(Renderer.module_namespace(data_module))

    if String.length(tag) + String.length(value) >= 76 do
      "  #{tag}:\n    #{value},"
    else
      "  #{tag}: #{value},"
    end
  end
end
